class AdminAccessKeyStore{constructor(){}normalize(t){const s=String(t||"").trim();return s.startsWith("ADMIN_ACCESS_KEY=")?s.slice(17).trim():s}}class AdminAuthApiClient{constructor(t,s){this.baseUrl=String(t||"").replace(/\/+$/,""),this.authEndpoint=this.normalizePath(s||"/api/admin/auth.php")}normalizePath(t){const s=String(t||"").trim();return""===s?"/api/admin/auth.php":/^https?:\/\//i.test(s)||s.startsWith("/")?s:`/${s}`}buildUrl(t){return/^https?:\/\//i.test(t)?t:`${this.baseUrl}${t}`}async verify(){try{const t=await fetch(this.buildUrl(this.authEndpoint),{method:"GET"});if(t.ok)return{ok:1,status:t.status,message:"Xác thực thành công"};const s=await this.readJsonSafe(t);return{ok:0,status:t.status,message:String(s?.message||s?.error||"Khóa truy cập không đúng")}}catch(t){return{ok:0,status:0,message:"Không thể kết nối máy chủ"}}}async login(t){if(!t)return{ok:0,status:0,message:"Vui lòng nhập khóa truy cập"};try{const s=await fetch(this.buildUrl(this.authEndpoint),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({password:t})}),e=await this.readJsonSafe(s);return s.ok&&e?.success?{ok:1,status:s.status,message:"Đăng nhập thành công"}:{ok:0,status:s.status,message:String(e?.message||e?.error||"Khóa truy cập không đúng")}}catch(t){return{ok:0,status:0,message:"Không thể kết nối máy chủ"}}}async readJsonSafe(t){try{return await t.json()}catch(t){return null}}}class AdminLoginPageController{constructor(t){this.form=t.form,this.passwordInput=t.passwordInput,this.errorMessage=t.errorMessage,this.statusMessage=t.statusMessage,this.submitButton=t.submitButton,this.submitText=t.submitText,this.redirectUrl=t.redirectUrl,this.keyStore=t.keyStore,this.authApi=t.authApi}init(){this.form&&this.passwordInput&&this.submitButton&&this.submitText&&(this.form.addEventListener("submit",t=>this.handleSubmit(t)),this.tryAutoLogin())}async tryAutoLogin(){this.showStatus("Đang kiểm tra phiên đăng nhập..."),(await this.authApi.verify()).ok?this.redirectToDashboard():this.hideStatus()}async handleSubmit(t){t.preventDefault();const s=this.passwordInput.value,e=this.keyStore.normalize(s);if(""===e)return void this.showError("Vui lòng nhập khóa truy cập");this.setLoading(1,"Đang đăng nhập..."),this.hideError(),this.showStatus("Đang xác thực với máy chủ...");const i=await this.authApi.login(e);if(!i.ok)return this.setLoading(0,"Đăng nhập"),this.hideStatus(),void this.showError(i.message||"Đăng nhập thất bại");this.redirectToDashboard()}setLoading(t,s){this.submitButton.disabled=t,this.submitText.textContent=s}showError(t){const s=String(t||"Đã xảy ra lỗi"),e=window.Swal;e&&"function"==typeof e.fire?e.fire({icon:"error",title:"Đăng nhập thất bại",text:s,confirmButtonText:"Đóng"}):this.errorMessage&&(this.errorMessage.textContent=s,this.errorMessage.classList.remove("hidden"))}hideError(){this.errorMessage&&(this.errorMessage.textContent="",this.errorMessage.classList.add("hidden"))}showStatus(t){this.statusMessage&&(this.statusMessage.textContent=String(t||""),this.statusMessage.classList.remove("hidden"))}hideStatus(){this.statusMessage&&(this.statusMessage.textContent="",this.statusMessage.classList.add("hidden"))}redirectToDashboard(){window.location.assign(this.redirectUrl)}}document.addEventListener("DOMContentLoaded",()=>{const t=document.documentElement,s=document.body,e=String(t?.dataset.baseUrl||"").trim(),i=String(s?.dataset.authEndpoint||"/api/admin/auth.php").trim(),n=String(s?.dataset.adminHome||"/adminkaishop").trim(),r=new AdminAccessKeyStore,a=new AdminAuthApiClient(e,i);new AdminLoginPageController({form:document.getElementById("loginForm"),passwordInput:document.getElementById("passwordInput"),errorMessage:document.getElementById("errorMsg"),statusMessage:document.getElementById("loginStatus"),submitButton:document.getElementById("loginSubmitBtn"),submitText:document.getElementById("loginSubmitText"),redirectUrl:`${e}${n}`,keyStore:r,authApi:a}).init()});